import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int m = Integer.parseInt(st.nextToken());int a = Integer.parseInt(st.nextToken());int b = Integer.parseInt(st.nextToken());int option1 = n * a;int option2 = (n / m) * b + (n % m) * a;int option3 = (n / m) * b + b;if (n % m != 0) {System.out.println(Math.min(option1, Math.min(option2, option3)));} else {System.out.println(Math.min(option1, (n / m) * b));}}}